css:
:scope { width: min(100%, 1031px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 1 / span 7; grid-row: 1 / span 22; font-family: var(--os-font-body); font-size: 46px; font-weight: 400; line-height: 1.2; letter-spacing: 0em; text-align: center; color: var(--os-color-text); }
.gx__i2 { grid-column: 6 / span 11; grid-row: 1 / span 57; aspect-ratio: 458 / 458; }
.gx__i3 { grid-column: 16 / span 7; grid-row: 4 / span 4; font-family: var(--os-font-body); font-size: 22px; font-weight: 400; line-height: 1.4; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i4 { grid-column: 16 / span 7; grid-row: 9 / span 4; font-family: var(--os-font-body); font-size: 22px; font-weight: 400; line-height: 1.4; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i5 { grid-column: 16 / span 7; grid-row: 14 / span 4; font-family: var(--os-font-body); font-size: 22px; font-weight: 400; line-height: 1.4; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i6 { grid-column: 17 / span 8; grid-row: 19 / span 4; font-family: var(--os-font-body); font-size: 22px; font-weight: 400; line-height: 1.4; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i7 { grid-column: 1 / span 7; grid-row: 23 / span 7; font-family: var(--os-font-body); font-size: 46px; font-weight: 400; line-height: 1.2; letter-spacing: 0em; text-align: center; color: var(--os-color-text); }
.gx__i8 { grid-column: 16 / span 7; grid-row: 24 / span 4; font-family: var(--os-font-body); font-size: 22px; font-weight: 400; line-height: 1.4; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i9 { grid-column: 1 / span 7; grid-row: 30 / span 22; font-family: var(--os-font-body); font-size: 46px; font-weight: 400; line-height: 1.2; letter-spacing: 0em; text-align: center; color: var(--os-color-text); }
.gx__i10 { grid-column: 16 / span 8; grid-row: 30 / span 4; font-family: var(--os-font-body); font-size: 22px; font-weight: 400; line-height: 1.4; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i11 { grid-column: 16 / span 8; grid-row: 35 / span 4; font-family: var(--os-font-body); font-size: 22px; font-weight: 400; line-height: 1.4; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i12 { grid-column: 16 / span 8; grid-row: 40 / span 4; font-family: var(--os-font-body); font-size: 22px; font-weight: 400; line-height: 1.4; letter-spacing: 0em; color: var(--os-color-text); }
@media (max-width: 767px) {
  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__i1 { font-family: var(--os-font-body); font-size: 37px; }
  .gx__i3 { font-family: var(--os-font-body); font-size: 18px; }
  .gx__i4 { font-family: var(--os-font-body); font-size: 18px; }
  .gx__i5 { font-family: var(--os-font-body); font-size: 18px; }
  .gx__i6 { font-family: var(--os-font-body); font-size: 18px; }
  .gx__i7 { font-family: var(--os-font-body); font-size: 37px; }
  .gx__i8 { font-family: var(--os-font-body); font-size: 18px; }
  .gx__i9 { font-family: var(--os-font-body); font-size: 37px; }
  .gx__i10 { font-family: var(--os-font-body); font-size: 18px; }
  .gx__i11 { font-family: var(--os-font-body); font-size: 18px; }
  .gx__i12 { font-family: var(--os-font-body); font-size: 18px; }
}
